exercises.starter:
let n: 1..=100 = read()
domain V = 1..=n
let a: [V]Int = read()
var cur = 0
var best = 0
for x in a:
    cur = max(0, cur + x)
    best max= cur
print(best)

@brute(main)
fn slow():
    var ans: ?Int = none
    for l in V:
        var total = 0
        for r in l..=V.last:
            total += a[r]
            ans max= total
    print(ans!)

