let n: 1..=100 = read()
domain V = 1..=n
let a: [V]Int = read()
var cur = a[V.first]
var best = cur
for v in V if v != V.first:
    cur = max(a[v], cur + a[v])
    best max= cur
print(best)

@brute(main)
fn slow():
    var ans: ?Int = none
    for l in V:
        var total = 0
        for r in l..=V.last:
            total += a[r]
            ans max= total
    print(ans!)
